import datetime, html.parser, json, re, sys, urllib.parse, urllib.request

class PageExtractor(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self.links = []
        self.skip = 0
        self.in_title = False
        self.title_parts = []
        self.current_link = None
    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs_dict = {k.lower(): v for k, v in attrs if k and v}
        if tag in {'script', 'style', 'noscript'}:
            self.skip += 1
            return
        if tag == 'title':
            self.in_title = True
        if tag == 'a' and attrs_dict.get('href'):
            self.current_link = {
                'href': attrs_dict.get('href', ''),
                'title': attrs_dict.get('title') or attrs_dict.get('aria-label') or '',
                'textParts': []
            }
    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in {'script', 'style', 'noscript'} and self.skip:
            self.skip -= 1
            return
        if tag == 'title':
            self.in_title = False
        if tag == 'a' and self.current_link:
            text = clean_text(' '.join(self.current_link.pop('textParts', [])))
            title = clean_text(self.current_link.get('title') or text)
            self.links.append({'href': self.current_link.get('href', ''), 'title': title, 'text': text})
            self.current_link = None
    def handle_data(self, data):
        if self.skip:
            return
        text = data.strip()
        if not text:
            return
        if self.in_title:
            self.title_parts.append(text)
        if self.current_link is not None:
            self.current_link['textParts'].append(text)
        self.parts.append(text)

def clean_text(value):
    return re.sub(r'\s+', ' ', str(value or '')).strip()

def extract_page(html_text, base_url):
    parser = PageExtractor()
    parser.feed(html_text)
    text = clean_text(' '.join(parser.parts))
    title = clean_text(' '.join(parser.title_parts))
    links = []
    seen = set()
    for raw in parser.links:
        href = raw.get('href', '')
        absolute = urllib.parse.urljoin(base_url, href)
        parsed = urllib.parse.urlparse(absolute)
        if parsed.scheme not in {'http', 'https'}:
            continue
        normalized = urllib.parse.urlunparse((parsed.scheme, parsed.netloc, parsed.path, '', parsed.query, ''))
        if normalized in seen:
            continue
        seen.add(normalized)
        links.append({'url': normalized, 'title': clean_text(raw.get('title') or raw.get('text') or normalized), 'text': clean_text(raw.get('text'))})
    return title, text, links

def normalize_urls(value):
    items = value if isinstance(value, list) else str(value or '').split(',')
    return [item.strip() for item in items if item and item.strip()]

def normalize_terms(value):
    if isinstance(value, list):
        items = value
    else:
        items = re.split(r'[,;]', str(value or ''))
    return [clean_text(item).lower() for item in items if clean_text(item)]

def same_site(url, seeds):
    host = urllib.parse.urlparse(url).netloc.lower().removeprefix('www.')
    return any(host == urllib.parse.urlparse(seed).netloc.lower().removeprefix('www.') for seed in seeds)

def blocked(url, patterns):
    lowered = url.lower()
    return any(pattern and pattern in lowered for pattern in patterns)

def relevance_score(link, terms):
    haystack = f"{link.get('title', '')} {link.get('text', '')} {link.get('url', '')}".lower()
    return sum(1 for term in terms if term in haystack)

def fetch_url(url, params, depth, source_url=None, link_title=''):
    fetched_at = datetime.datetime.utcnow().isoformat(timespec='seconds') + 'Z'
    req = urllib.request.Request(url, headers={'User-Agent': 'MCPStudio-PythonRuntimeTool/1.0'})
    try:
        with urllib.request.urlopen(req, timeout=int(params.get('requestTimeoutSeconds', 20))) as resp:
            raw = resp.read(int(params.get('maxBytesPerUrl', 500000)))
            encoding = resp.headers.get_content_charset() or 'utf-8'
            html_text = raw.decode(encoding, errors='replace')
            page_title, text, links = extract_page(html_text, resp.geturl())
            return {
                'url': url,
                'finalUrl': resp.geturl(),
                'sourceUrl': source_url,
                'linkTitle': link_title,
                'depth': depth,
                'pageTitle': page_title,
                'statusCode': resp.status,
                'contentType': resp.headers.get('content-type', ''),
                'fetchedAtUTC': fetched_at,
                'success': True,
                'text': text[:int(params.get('maxTextCharsPerUrl', 20000))],
                'links': links
            }
    except Exception as exc:
        return {
            'url': url,
            'sourceUrl': source_url,
            'linkTitle': link_title,
            'depth': depth,
            'fetchedAtUTC': fetched_at,
            'success': False,
            'error': f'{type(exc).__name__}: {exc}'
        }

def crawl(params):
    seeds = normalize_urls(params.get('urls', params.get('url', '')))
    terms = normalize_terms(params.get('relevantTitleTerms', 'border, crossing, customs, checkpoint, security, statement, announcement, travel, region, conflict, peace, Abkhazia, South Ossetia, Armenia, Azerbaijan, Georgia, Russia, Caucasus'))
    blocked_patterns = normalize_terms(params.get('blockedUrlPatterns', 'facebook.com, instagram.com, youtube.com, t.me, telegram.me, whatsapp, mailto:'))
    max_depth = max(0, min(int(params.get('maxCrawlDepth', 1)), 2))
    max_links_per_page = max(1, int(params.get('maxLinksPerPage', 8)))
    max_pages = max(len(seeds), int(params.get('maxPages', 24)))
    pages = []
    discovered = []
    selected = []
    queue = [{'url': url, 'depth': 0, 'sourceUrl': None, 'linkTitle': ''} for url in seeds]
    visited = set()

    while queue and len(pages) < max_pages:
        item = queue.pop(0)
        url = item['url']
        if url in visited or blocked(url, blocked_patterns):
            continue
        visited.add(url)
        page = fetch_url(url, params, item['depth'], item.get('sourceUrl'), item.get('linkTitle', ''))
        links = page.pop('links', []) if page.get('success') else []
        pages.append(page)
        if not page.get('success') or item['depth'] >= max_depth:
            continue

        candidates = []
        for link in links:
            if not same_site(link['url'], seeds) or blocked(link['url'], blocked_patterns) or link['url'] in visited:
                continue
            score = relevance_score(link, terms)
            record = {
                'sourceUrl': page.get('finalUrl', url),
                'url': link['url'],
                'title': link.get('title', ''),
                'anchorText': link.get('text', ''),
                'depth': item['depth'] + 1,
                'titleRelevanceScore': score
            }
            discovered.append(record)
            if score > 0:
                candidates.append(record)
        candidates.sort(key=lambda rec: (-rec['titleRelevanceScore'], rec['title'], rec['url']))
        for record in candidates[:max_links_per_page]:
            selected.append(record)
            queue.append({'url': record['url'], 'depth': record['depth'], 'sourceUrl': record['sourceUrl'], 'linkTitle': record['title']})

    return {
        'country': params.get('country', ''),
        'seedUrls': seeds,
        'fetchedAtUTC': datetime.datetime.utcnow().isoformat(timespec='seconds') + 'Z',
        'maxCrawlDepth': max_depth,
        'titleRelevanceTerms': terms,
        'pagesFetched': pages,
        'discoveredLinks': discovered[:200],
        'selectedLinks': selected[:100],
        'selectionNote': 'Python applies a bounded title/anchor-text prefilter. Downstream LLM agents must audit selectedLinks and decide final relevance from link titles, page titles, source text, and the user request.'
    }

